use crate::models::customer::Customer; use crate::errors::{Result, AppError}; use tauri::State; use crate::database::Database; use rusqlite::params; #[tauri::command] pub fn get_customers(db: State<'_, Database>) -> Result<Vec<Customer>> { let conn = db.get_connection()?; let mut stmt = conn.prepare("SELECT id, name, phone, address, notes, status, created_at, updated_at FROM customers ORDER BY name ASC")?; let customers = stmt.query_map([], |row| { Ok(Customer { id: row.get(0)?, name: row.get(1)?, phone: row.get(2)?, address: row.get(3)?, notes: row.get(4)?, status: row.get(5)?, created_at: row.get(6)?, updated_at: row.get(7)? }) })?.collect::<std::result::Result<Vec<_>, _>>()?; Ok(customers) } #[tauri::command] pub fn create_customer(db: State<'_, Database>, name: String, phone: Option<String>, address: Option<String>, notes: Option<String>) -> Result<Customer> { let mut conn = db.get_connection()?; let tx = conn.transaction()?; tx.execute("INSERT INTO customers (name, phone, address, notes) VALUES (?1, ?2, ?3, ?4)", params![name, phone, address, notes])?; let id = tx.last_insert_rowid(); tx.execute("INSERT INTO utang_accounts (customer_id, status) VALUES (?1, 'ACTIVE')", params![id])?; tx.commit()?; let conn2 = db.get_connection()?; let customer = conn2.query_row("SELECT id, name, phone, address, notes, status, created_at, updated_at FROM customers WHERE id = ?1", params![id], |row| { Ok(Customer { id: row.get(0)?, name: row.get(1)?, phone: row.get(2)?, address: row.get(3)?, notes: row.get(4)?, status: row.get(5)?, created_at: row.get(6)?, updated_at: row.get(7)? }) })?; Ok(customer) } #[tauri::command] pub fn update_customer(db: State<'_, Database>, id: i64, name: String, phone: Option<String>, address: Option<String>, notes: Option<String>, status: String) -> Result<Customer> { let conn = db.get_connection()?; conn.execute("UPDATE customers SET name = ?1, phone = ?2, address = ?3, notes = ?4, status = ?5, updated_at = CURRENT_TIMESTAMP WHERE id = ?6", params![name, phone, address, notes, status, id])?; let customer = conn.query_row("SELECT id, name, phone, address, notes, status, created_at, updated_at FROM customers WHERE id = ?1", params![id], |row| { Ok(Customer { id: row.get(0)?, name: row.get(1)?, phone: row.get(2)?, address: row.get(3)?, notes: row.get(4)?, status: row.get(5)?, created_at: row.get(6)?, updated_at: row.get(7)? }) })?; Ok(customer) } #[tauri::command] pub fn delete_customer(db: State<'_, Database>, id: i64) -> Result<()> { let conn = db.get_connection()?; let mut stmt = conn.prepare("SELECT COUNT(*) FROM sales WHERE customer_id = ?1")?; let count: i64 = stmt.query_row(params![id], |row| row.get(0))?; if count > 0 { return Err(AppError::BusinessRule("Cannot delete customer with sales history.".into())); } conn.execute("DELETE FROM utang_accounts WHERE customer_id = ?1", params![id])?; conn.execute("DELETE FROM customers WHERE id = ?1", params![id])?; Ok(()) }
